<template><div class="page-head"><div><h2>经营概览</h2><div class="muted">宠物零食商城实时业务数据</div></div></div><div class="stats"><ElCard v-for="x in cards" :key="x.label" class="card"><span>{{x.label}}</span><strong>{{x.value}}</strong></ElCard></div></template><script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api';const data=ref<any>({});const cards=computed(()=>[{label:'用户总数',value:data.value.userCount||0},{label:'订单总数',value:data.value.orderCount||0},{label:'待支付订单',value:data.value.pendingPaymentCount||0},{label:'已支付金额',value:`¥${data.value.paidAmountYuan||0}`}]);onMounted(async()=>data.value=await api.overview())</script><style scoped>.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.card span,.card strong{display:block}.card span{color:#9299a9}.card strong{font-size:32px;margin-top:18px}</style>
